    public void test_reportsTheCurrentNodeAndFraction() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        List<SNode> toRun = ListSequence.fromList(new ArrayList<SNode>());
        ListSequence.fromList(toRun).addElement(getAnnotatedNode("a"));
        ListSequence.fromList(toRun).addElement(getAnnotatedNode("b"));
        final List<SNode> finalToRun = toRun;
        ProgressIndicatorBase indicator = new ProgressIndicatorBase();

        ProgressManager.getInstance().runProcess(() -> RunManuallyWithProgress.runNodes(null, finalToRun, ListSequence.fromList(new ArrayList<SNode>())), indicator);

        assert !(indicator.isIndeterminate()) : "the fraction is known";
        assert indicator.getFraction() == 0.5 : "fraction before the last node";
        assert "second".equals(indicator.getText2()) : "name of the last node";
      });
    }
    public void test_elapsedShowsTenthsOfSeconds() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        assert "0.0 s".equals(ProgressOverlay.elapsed(0)) : "zero";
        assert "1.2 s".equals(ProgressOverlay.elapsed(1299)) : "rounds down";
        assert "75.0 s".equals(ProgressOverlay.elapsed(75000)) : "over a minute";
      });
    }
    public void test_fitKeepsTextThatFitsAndShortensTheRest() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        FontMetrics metrics = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics().getFontMetrics(new Font("Dialog", Font.PLAIN, 13));
        String text = "a rather long text that does not fit";
        int width = metrics.stringWidth(text);

        assert "".equals(ProgressOverlay.fit(null, metrics, 100)) : "null text";
        assert text.equals(ProgressOverlay.fit(text, metrics, width)) : "exact fit";
        String shortened = ProgressOverlay.fit(text, metrics, width / 2);
        assert shortened.endsWith("...") : "marked as shortened";
        assert metrics.stringWidth(shortened) <= width / 2 : "within the width";
        assert "...".equals(ProgressOverlay.fit(text, metrics, 0)) : "no room at all";
      });
    }
    public void test_overlayLandsOnTheSameSpotOnEveryScale() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        double[] scales = {1.0, 1.5, 2.0};
        for (double scale : scales) {
          BufferedImage image = ScaledRootPane.paintOverlay(scale, null);
          double left = 10 + 70 * scale;
          double right = 10 + 530 * scale;
          double row = 20 + 110 * scale;
          assert ScaledRootPane.paintedAt(image, left + 3, row) : "left edge inside";
          assert !(ScaledRootPane.paintedAt(image, left - 3, row)) : "left edge outside";
          assert ScaledRootPane.paintedAt(image, right - 3, row) : "right edge inside";
          assert !(ScaledRootPane.paintedAt(image, right + 3, row)) : "right edge outside";
        }
      });
    }
    public void test_resettingTheTransformKeepsTheClip() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        BufferedImage image = ScaledRootPane.paintOverlay(2.0, new Rectangle(0, 0, 300, 400));
        double row = 20 + 110 * 2.0;
        double clipEdge = 10 + 300 * 2.0;
        assert ScaledRootPane.paintedAt(image, clipEdge - 3, row) : "inside the clip";
        assert !(ScaledRootPane.paintedAt(image, clipEdge + 3, row)) : "outside the clip";
      });
    }
